"""Migrated validation rules for OPP_MASTER."""

from decimal import Decimal, InvalidOperation


def _value(row: dict | None, key: str) -> object:
    if row is None:
        return ""
    value = row.get(key, "")
    return "" if value is None else value


def _is_empty(value: object) -> bool:
    return value is None or value == ""


def _nvl(value: object, default: object) -> object:
    return default if _is_empty(value) else value


def _number(value: object) -> Decimal:
    if _is_empty(value):
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _date_ge(left: object, right: object) -> bool:
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using migrated VRL rules."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amt, 0)) >= Decimal(0)):
            errors.append(_error("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0))):
            errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_error("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and close_dt == "00000000")):
            errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage == Decimal(10))
            or (stat_cd == "Q" and stage == Decimal(25))
            or (stat_cd == "N" and stage == Decimal(60))
            or (stat_cd == "W" and stage == Decimal(100))
            or (stat_cd == "L" and stage == Decimal(0))
        )
        if not valid_stage:
            errors.append(_error("E3006", "Stage percent inconsistent with status"))

    # OPP-007
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            errors.append(_error("E3007", "Close date in past", "WARN"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
